def create_sample_data():
    """Generate sample bank management data."""
    
    # Database connection
    engine = create_engine(os.getenv("DATABASE_URL", settings.database_url))
    SessionLocal = sessionmaker(bind=engine)
    db = SessionLocal()
    
    try:
        print("🚀 Generating sample bank data...")
        print("🧹 Dropping existing tables...")
        Base.metadata.drop_all(engine)
        # Create database tables first
        print("🗃️ Creating database tables...")
        Base.metadata.create_all(engine)
        
        # Create users
        print("👥 Creating users...")
        user_map = {}
        for user_data in BANK_USERS:
            user = User(
                name=user_data["name"],
                email=user_data["email"],
                hashed_password=SecurityManager.get_password_hash("password123"),
                role=user_data["role"],
                is_active=True,
                is_verified=True
            )
            db.add(user)
            db.flush()
            user_map[user_data["name"]] = user
        
        # Create domains
        print("🏢 Creating domains...")
        domain_map = {}
        for domain_data in BANK_DOMAINS:
            steward = random.choice(list(user_map.values()))
            domain = Domain(
                name=domain_data["name"],
                description=domain_data["description"],
                color=domain_data["color"],
                steward_id=steward.id
            )
            db.add(domain)
            db.flush()
            domain_map[domain_data["name"]] = domain
        
        # Create data sources
        print("🔌 Creating data sources...")
        data_source_map = {}
        for ds_data in BANK_DATA_SOURCES:
            data_source = DataSource(
                name=ds_data["name"],
                type=ds_data["type"],
                description=ds_data["description"],
                base64_url=ds_data.get("base64_url"),
                connection_config=ds_data["connection_config"],
                is_active=True,
                connection_status="success"
            )
            db.add(data_source)
            db.flush()
            data_source_map[ds_data["name"]] = data_source
        
        # Create tags
        print("🏷️ Creating tags...")
        tag_map = {}
        for tag_data in BANK_TAGS:
            tag = Tag(
                name=tag_data["name"],
                description=tag_data["description"],
                color=tag_data["color"],
                is_active=True
            )
            db.add(tag)
            db.flush()
            tag_map[tag_data["name"]] = tag
        
        # Create tables and columns
        print("📊 Creating tables and columns...")
        table_map = {}
        active_tables = 0
        inactive_tables = 0


        # Create governance rules
        print("📋 Creating governance rules...")
        governance_rules_count = 0
        
        for rule_data in GOVERNANCE_RULES:
            # Check if GovernanceRule model exists and has the expected structure
            try:
                governance_rule = GovernanceRule(
                    rule_id=rule_data["rule_id"],
                    rules=rule_data["rules"],
                    status=rule_data["status"],
                    category=rule_data["category"],
                    priority=rule_data["priority"]
                )
                db.add(governance_rule)
                governance_rules_count += 1
            except Exception as e:
                print(f"⚠️  Warning: Could not create governance rule {rule_data['rule_id']}. Make sure the GovernanceRule model exists. Error: {e}")
                continue
        
        print(f"  • Governance Rules: {governance_rules_count}")
        
        # for table_data in BANK_TABLES:
        #     domain = domain_map[table_data["domain"]]
        #     data_source = data_source_map[table_data["data_source"]]
        #     owner = random.choice(list(user_map.values()))
            
        #     table = Table(
        #         name=table_data["name"],
        #         schema_name=table_data["schema_name"],
        #         description=table_data["description"],
        #         data_source_id=data_source.id,
        #         domain_id=domain.id,
        #         owner_id=owner.id,
        #         sensitivity_level=table_data.get("sensitivity", "internal"),
        #         is_certified=table_data.get("is_certified", False),
        #         is_active=table_data["is_active"]
        #     )
        #     db.add(table)
        #     db.flush()
        #     table_map[table_data["name"]] = table

        for table_data in BANK_TABLES:
            domain = domain_map[table_data["domain"]]
            data_source = data_source_map[table_data["data_source"]]
            owner = random.choice(list(user_map.values()))
            base64_url_value = data_source.base64_url if hasattr(data_source, 'base64_url') else None
            table = Table(
                name=table_data["name"],
                schema_name=table_data["schema_name"],
                description=table_data["description"],
                data_source_id=data_source.id,
                domain_id=domain.id,
                owner_id=owner.id,
                sensitivity_level=table_data.get("sensitivity", "internal"),
                is_certified=table_data.get("is_certified", False),
                is_active=table_data["is_active"],
                upstream_tables=table_data.get("upstream_tables", []),
                downstream_tables=table_data.get("downstream_tables", []),
                data_source_base64_url=base64_url_value
            )
            db.add(table)
            db.flush()
            table_map[table_data["name"]] = table
            
            # Track active/inactive counts
            if table_data["is_active"]:
                active_tables += 1
            else:
                inactive_tables += 1
            
            # Create columns
            for i, col_data in enumerate(table_data["columns"]):
                column = Column(
                    table_id=table.id,
                    name=col_data["name"],
                    data_type=col_data["data_type"],
                    description=col_data.get("description", ""),
                    is_primary_key=col_data.get("is_primary_key", False),
                    is_foreign_key=col_data.get("is_foreign_key", False),
                    is_pii=col_data.get("is_pii", False),
                    sensitivity_level=col_data.get("sensitivity_level", "internal"),
                    ordinal_position=i + 1,
                    is_nullable=not col_data.get("is_primary_key", False)
                )
                db.add(column)
            
            # Create table stats
            stats = TableStats(
                table_id=table.id,
                row_count=random.randint(1000, 1000000),
                size_bytes=random.randint(1024*1024, 1024*1024*1024),
                quality_score=random.randint(75, 100),
                query_count_last_30d=random.randint(10, 500),
                unique_users_last_30d=random.randint(3, 20),
                last_updated=datetime.utcnow() - timedelta(days=random.randint(0, 30))
            )
            db.add(stats)
            
            # Add some tags to tables
            relevant_tags = []
            if "customer" in table_data["name"].lower() or any(col.get("is_pii") for col in table_data["columns"]):
                relevant_tags.extend([tag_map["PII"], tag_map["Customer"]])
            if "transaction" in table_data["name"].lower():
                relevant_tags.extend([tag_map["Transaction"], tag_map["Financial"]])
            if "risk" in table_data["name"].lower() or "fraud" in table_data["name"].lower():
                relevant_tags.extend([tag_map["Risk"], tag_map["Compliance"]])
            if "loan" in table_data["name"].lower():
                relevant_tags.extend([tag_map["Loan"], tag_map["Financial"]])
            if "investment" in table_data["name"].lower():
                relevant_tags.extend([tag_map["Investment"], tag_map["Financial"]])
            if "compliance" in table_data["name"].lower() or "audit" in table_data["name"].lower():
                relevant_tags.extend([tag_map["Compliance"], tag_map["Critical"]])
            if "analytics" in table_data["name"].lower():
                relevant_tags.extend([tag_map["Analytics"]])
            if not table_data["is_active"]:
                relevant_tags.extend([tag_map["Archived"]])
            
            # Add tags to table
            for tag in set(relevant_tags[:4]):  # Limit to 4 unique tags per table
                table_tag = TableTag(
                    table_id=table.id,
                    tag_id=tag.id,
                    created_by=owner.id
                )
                db.add(table_tag)
        
        db.commit()
        print("✅ Sample data created successfully!")
        
        # Print summary
        print("\n📈 Data Summary:")
        print(f"  • Users: {len(BANK_USERS)}")
        print(f"  • Domains: {len(BANK_DOMAINS)}")
        print(f"  • Data Sources: {len(BANK_DATA_SOURCES)}")
        print(f"  • Tables: {len(BANK_TABLES)}")
        print(f"    - Active Tables: {active_tables}")
        print(f"    - Inactive Tables: {inactive_tables}")
        print(f"  • Tags: {len(BANK_TAGS)}")
        print(f"  • Governance Rules: {governance_rules_count}")
        

        print("\n🔗 Lineage Summary:")
        for table_name in ["customers", "accounts", "transactions", "loans"]:
            if table_name in table_map:
                table = table_map[table_name]
                print(f"  • {table_name}:")
                print(f"    - Upstream: {table.upstream_tables}")
                print(f"    - Downstream: {table.downstream_tables}")
        
        
        # Print login info
        print("\n🔐 Login Information:")
        print("  Admin User:")
        print(f"    Email: {BANK_USERS[0]['email']}")
        print("    Password: password123")
        print("\n  Other users have the same password: password123")
        
    except Exception as e:
        db.rollback()
        print(f"❌ Error creating sample data: {e}")
        raise
    finally:
        db.close()


if __name__ == "__main__":
    create_sample_data()


